function zodPhoneNumber() {
  return z.string().transform((val, ctx) => {
    if (!val) {
      return val;
    }
    let parsed;
    try {
      parsed = parsePhoneNumberWithError(val, {
        defaultCountry: "US",
        extract: false
      });
    } catch {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Not a valid phone number"
      });
      return z.NEVER;
    }
    if (!parsed.isValid()) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Not a valid phone number"
      });
      return z.NEVER;
    }
    return parsed.number.toString();
  });
}
