type FinalRunaroundClueLetterResult = {
  message: string;
  success?: boolean | undefined;
};

type FinalRunaroundClueLetterResponse =
  | { success: true; data: Record<string, string>[] }
  | { success: false; data: null };

const getFinalRunaroundClueLetterResponse = (
  letter: string,
  code: string,
): FinalRunaroundClueLetterResponse => {
  const target = letter.toUpperCase();
  if (
    !Object.prototype.hasOwnProperty.call(FINAL_RUNAROUND_CODES, target) ||
    FINAL_RUNAROUND_CODES[target as keyof typeof FINAL_RUNAROUND_CODES] !== code
  ) {
    return { success: false, data: null };
  }

  return {
    success: true,
    data: FINAL_RUNAROUND_CLUES.map((clue) => {
      const matches: Record<string, string> = {};
      for (let i = 0; i < clue.length; i++) {
        const ch = clue[i];
        if (ch.toUpperCase() === target) {
          matches[String(i)] = ch;
        }
      }
      return matches;
    }),
  };
};

const CluesDisplay = ({ isArchival }: { isArchival: boolean }) => {
  const [selectedLetter, setSelectedLetter] = React.useState<string>("");
  const [code, setCode] = React.useState<string>("");
  const [clues, setClues] = React.useState<string[]>(() => {
    if (typeof window !== "undefined") {
      try {
        const stored = localStorage.getItem(HUMMING_STRING_CLUES_KEY);
        if (stored) {
          const parsed = JSON.parse(stored) as string[];
          if (Array.isArray(parsed) && parsed.length === CLUES.length) {
            return parsed;
          }
        }
      } catch {
        // Ignore parse errors
      }
    }
    return [...CLUES];
  });
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [result, setResult] = useState<FinalRunaroundClueLetterResult | null>(
    null,
  );
  const [revealedLetters, setRevealedLetters] = React.useState<Set<string>>(
    () => {
      if (typeof window !== "undefined") {
        try {
          const stored = localStorage.getItem(HUMMING_STRING_REVEALED_KEY);
          if (stored) {
            const parsed = JSON.parse(stored) as string[];
            if (Array.isArray(parsed)) {
              return new Set(parsed);
            }
          }
        } catch {
          // Ignore parse errors
        }
      }
      return new Set();
    },
  );

  // Persist clues to localStorage
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      localStorage.setItem(HUMMING_STRING_CLUES_KEY, JSON.stringify(clues));
    } catch {
      // Ignore storage errors
    }
  }, [clues]);

  // Persist revealed letters to localStorage
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      localStorage.setItem(
        HUMMING_STRING_REVEALED_KEY,
        JSON.stringify([...revealedLetters]),
      );
    } catch {
      // Ignore storage errors
    }
  }, [revealedLetters]);

  const applySuccessfulReveal = (data: Record<string, string>[]) => {
    if (data.length !== clues.length) return;
    setClues((prev) =>
      prev.map((clue, clueIdx) => {
        const dict = data[clueIdx];
        if (!dict || typeof dict !== "object") return clue;
        const chars = clue.split("");
        for (const [idxStr, ch] of Object.entries(dict)) {
          const idx = Number(idxStr);
          if (!Number.isInteger(idx)) continue;
          if (idx < 0 || idx >= chars.length) continue;
          if (typeof ch !== "string" || ch.length !== 1) continue;
          chars[idx] = ch;
        }
        return chars.join("");
      }),
    );
  };

  const submit = async () => {
    const canonicalLetter = selectedLetter.toUpperCase();
    if (canonicalLetter.length !== 1) {
      setResult({
        message: "Enter a single letter.",
        success: false,
      });
      return;
    }

    if (isArchival) {
      const response = getFinalRunaroundClueLetterResponse(
        canonicalLetter,
        code,
      );
      if (response.success) {
        applySuccessfulReveal(response.data);
        setResult({
          message: "Success.",
          success: true,
        });
        setRevealedLetters((prev) => new Set([...prev, canonicalLetter]));
      } else {
        setResult({
          message: "Incorrect code.",
          success: false,
        });
      }
      return;
    }

    setIsSubmitting(true);
    try {
      const baseUrl = `${window.apiBaseUrl ?? location.origin}/api`;
      const apiClient = newClient(baseUrl, undefined);
      const response = await apiClient.finalRunaroundClueLetter({
        body: { letter: canonicalLetter, code: code },
      });

      const success: boolean =
        response.status === 200 &&
        response.body &&
        typeof response.body === "object" &&
        "success" in response.body
          ? Boolean((response.body as { success: unknown }).success)
          : false;
      const message =
        response.body &&
        typeof response.body === "object" &&
        "message" in response.body
          ? String((response.body as { message: unknown }).message)
          : "";

      if (response.status === 200) {
        if (success) {
          const data =
            response.body &&
            typeof response.body === "object" &&
            "data" in response.body
              ? ((response.body as { data: unknown }).data as Record<
                  string,
                  string
                >[])
              : [];

          applySuccessfulReveal(data);
          setResult({
            message: "Success.",
            success: success,
          });
          setRevealedLetters((prev) => new Set([...prev, canonicalLetter]));
        } else {
          setResult({
            message: "Incorrect code.",
            success: success,
          });
        }
      } else if (response.status === 400) {
        setResult({
          message: message,
          success: success,
        });
      } else if (response.status === 429) {
        const retryAfterStr =
          response.body &&
          typeof response.body === "object" &&
          "retryAfter" in response.body
            ? String((response.body as { retryAfter: unknown }).retryAfter)
            : null;

        const retryAfterMs = retryAfterStr ? Date.parse(retryAfterStr) : NaN;
        const fallbackMs = Date.now() + 60_000;
        const untilMs = Number.isFinite(retryAfterMs)
          ? retryAfterMs
          : fallbackMs;

        const delayMs = Math.max(0, untilMs - Date.now());
        setResult({
          message: `Rate limited for ${Math.ceil(delayMs / 1000)} seconds.`,
          success: success,
        });
      }
    } catch {
      setResult({
        message: "Request failed.",
        success: false,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const submitDisabled = isSubmitting;

  return (
    <div className="flex flex-col gap-4">
      <form
        className="flex flex-wrap items-end gap-3"
        onSubmit={(e) => {
          e.preventDefault();
          void submit();
        }}
      >
        <label className="flex flex-col gap-1">
          <span className="text-sm font-medium">Letter</span>
          <input
            className="border border-gray-400 rounded px-2 py-1 font-mono w-20"
            value={selectedLetter}
            onChange={(e) => {
              const next = e.target.value.toUpperCase().replace(/[^A-Z]/g, "");
              setSelectedLetter(next.slice(0, 1));
            }}
          />
        </label>

        <label className="flex flex-col gap-1">
          <span className="text-sm font-medium">Code</span>
          <input
            className="border border-gray-400 rounded px-2 py-1 font-mono w-28"
            value={code}
            maxLength={3}
            onChange={(e) => {
              setCode(e.target.value);
            }}
          />
        </label>

        <button
          type="submit"
          disabled={submitDisabled}
          className={[
            "border border-gray-400 rounded px-2 py-1 font-mono",
            submitDisabled ? "bg-gray-200" : "bg-white hover:bg-gray-50",
          ].join(" ")}
        >
          {"Submit"}
        </button>

        {result?.message ? (
          <div
            className={[
              "font-medium",
              result.success ? "text-green-700" : "text-yellow-700",
            ].join(" ")}
          >
            {result.message}
          </div>
        ) : null}
      </form>

      <div className="flex flex-wrap gap-2 select-none">
        {LETTERS_A_TO_Z.map((letter) => {
          const isRevealed = revealedLetters.has(letter);
          return (
            <div
              key={letter}
              className={[
                "w-6 h-6 border border-gray-500 flex items-center justify-center font-mono text-sm",
                isRevealed ? "bg-[#00c417]" : "bg-white hover:bg-gray-50",
              ].join(" ")}
            >
              {letter}
            </div>
          );
        })}
      </div>

      <div className="flex flex-col gap-3">
        {clues.map((text, idx) => (
          <div
            key={`${CLUE_IMAGES[idx]}::${idx}`}
            className="flex items-start gap-3"
            style={{ margin: "4px 0" }}
          >
            <div
              className="font-mono text-2xl whitespace-pre-wrap break-normal flex-1 tracking-[0.08em]"
              style={{
                fontFamily:
                  "'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace",
              }}
            >
              {text}
            </div>
            <div className="w-[300px] flex justify-start shrink-0">
              <img
                src={CLUE_IMAGES[idx]}
                alt=""
                className="max-h-24"
                loading="lazy"
                style={{
                  height: "30px",
                  width: "300px",
                }}
              />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const glitchifyText = (text: string) => {
  // Split into "word" and whitespace tokens so we preserve spacing exactly.
  const tokens = text.split(/(\s+)/);
  return tokens.map((token, idx) => {
    if (token.trim() === "") return token;
    return (
      <GlitchEffect
        key={`${token}-${idx}`}
        size="large"
        className="inline-block"
      >
        {token}
      </GlitchEffect>
    );
  });
};

type PuzzleProps = Pick<PuzzleContentProps, "teamState">;

const Puzzle = ({ teamState }: PuzzleProps) => {
  const isArchival = teamState.gates_satisfied.includes("archival_mode");
  const [pulledLetters, setPulledLetters] = useState<string[]>([]);
  const [pulledShapes, setPulledShapes] = useState<string[][]>([]);

  const pullLetter = () => {
    const remaining = GACHA_LETTER_PULLS.filter(
      (p) => !pulledLetters.includes(p),
    );
    if (remaining.length > 0) {
      const randomItem =
        remaining[Math.floor(Math.random() * remaining.length)];
      setPulledLetters([...pulledLetters, randomItem]);
    }
  };

  const pullShape = () => {
    const remaining = GACHA_SHAPE_PULLS.filter(
      (p) => !pulledShapes.some((s) => s[0] === p[0] && s[1] === p[1]),
    );
    if (remaining.length > 0) {
      const randomItem =
        remaining[Math.floor(Math.random() * remaining.length)];
      setPulledShapes([...pulledShapes, randomItem]);
    }
  };

  return (
    <div id="puzzle-content-root">
      <style>{GlitchStyles}</style>

      <>
        {isArchival && (
          <AuthorsNote>
            This finale included live clue validation during the event. The
            archival site keeps the materials below, with clue checking handled
            entirely in the browser.
          </AuthorsNote>
        )}
        <FlavorText>
          To help the Keepers finish the job, you&apos;ll need to innovate a new
          field of monster investigation. What exactly do you need to do?
          <br />
          <hr />
          {glitchifyText(
            "The Keeper of Runes and the Keeper of Memory have the clues you need, but you'll need to see past the distortions caused by their powers.",
          )}
        </FlavorText>
        <div>
          <CluesDisplay isArchival={isArchival} />
        </div>
        <PostHuntDetails>
          <p>
            Teams were told that the Keeper of Fate had set up 2 gacha machines,
            one with letters from the Keeper of Runes and one with hexagon and
            heptagon tiles from the Keeper of Precepts and the Keeper of
            Structure, respectively. Teams were also given 12 additional puzzles
            created by the Puzzmon. They received 4 gacha tokens to start and
            could earn 3 more tokens for each of the 12 additional puzzles
            solved. The twelve puzzles are shown below and you can use the
            answer checker at the top of the page to verify your answers to
            those puzzles. There are also buttons below that you can use to
            simulate pulling from the gacha machines. If you want physical
            copies of the shape tiles, you can print this{" "}
            <a
              href={shape_tiles}
              download
              className="text-blue-600 hover:underline"
            >
              PDF
            </a>{" "}
            double-sided, flipping along the long edge.
          </p>
          <ImageGallery
            images={[
              { src: puzzle_dactylinion, alt: "Dactylinion Puzzle" },
              { src: puzzle_dukdukgoop, alt: "Dukdukgoop Puzzle" },
              { src: puzzle_featherbrain, alt: "Featherbrain Puzzle" },
              { src: puzzle_hepanchart, alt: "Hepanchart Puzzle" },
              { src: puzzle_humidefta, alt: "Humidefta Puzzle" },
              { src: puzzle_kneedle, alt: "Kneedle Puzzle" },
              { src: puzzle_knightbulb, alt: "Knightbulb Puzzle" },
              { src: puzzle_perkepsu, alt: "Perkepsu Puzzle" },
              { src: puzzle_pointdexter, alt: "Pointdexter Puzzle" },
              { src: puzzle_sheriff_shaffour, alt: "Sheriff Shaffour Puzzle" },
              { src: puzzle_steve, alt: "Steve Puzzle" },
              { src: puzzle_ttattell, alt: "Ttattell Puzzle" },
            ]}
          />
          <div className="mt-8 flex flex-col md:flex-row gap-8">
            <div className="flex flex-col gap-4 flex-1">
              <h3 className="text-xl font-bold border-b border-gray-200 pb-2">
                Letter Gacha Machine
              </h3>
              <ButtonSecondary
                onClick={pullLetter}
                disabled={pulledLetters.length >= GACHA_LETTER_PULLS.length}
                className="w-fit"
              >
                {pulledLetters.length >= GACHA_LETTER_PULLS.length
                  ? "No more letter pulls available"
                  : "Pull Letters"}
              </ButtonSecondary>
              <div className="flex flex-wrap gap-2 mb-2">
                {pulledLetters.map((pull, i) => (
                  <div
                    key={i}
                    className="bg-gray-100 border border-gray-300 rounded px-3 py-1 font-mono"
                  >
                    {pull}
                  </div>
                ))}
              </div>
            </div>

            <div className="flex flex-col gap-4 flex-1">
              <h3 className="text-xl font-bold border-b border-gray-200 pb-2">
                Shape Gacha Machine
              </h3>
              <ButtonSecondary
                onClick={pullShape}
                disabled={pulledShapes.length >= GACHA_SHAPE_PULLS.length}
                className="w-fit"
              >
                {pulledShapes.length >= GACHA_SHAPE_PULLS.length
                  ? "No more shape pulls available"
                  : "Pull Shapes"}
              </ButtonSecondary>
              <div className="flex flex-col gap-4 mb-2">
                {pulledShapes.map((pair, i) => (
                  <div key={i} className="flex gap-4 items-center">
                    <a href={pair[0]} target="_blank" rel="noopener noreferrer">
                      <img
                        src={pair[0]}
                        alt="Shape 1"
                        className="w-20 h-20 object-contain border border-gray-200 rounded p-1 hover:border-blue-400 transition-colors"
                      />
                    </a>
                    <a href={pair[1]} target="_blank" rel="noopener noreferrer">
                      <img
                        src={pair[1]}
                        alt="Shape 2"
                        className="w-20 h-20 object-contain border border-gray-200 rounded p-1 hover:border-blue-400 transition-colors"
                      />
                    </a>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </PostHuntDetails>
      </>
    </div>
  );
};

export default Puzzle;
